mapper.select:
select co.lectureInfoId,co.commentId,co.status,tr.title,dict.habit_name as title,fo.name,co.commentInfo,co.comImg,co.commentTime from yh_health_lecture_comment co inner join yh_user_reginfo fo on co.usercode=fo.user_code left join yh_life_habit_dict dict on co.lectureInfoId=dict.id left join yh_health_lecture_info tr on co.lectureInfoId=tr.infoId
co.pid=0
AND ( tr.title like CONCAT('%',#{title},'%' ) or dict.habit_name like CONCAT('%',#{title},'%' ) )
AND ( fo.Org_Code like CONCAT('%',#{orgCode},'%' ) )
and co.status = #{status,jdbcType=INTEGER}
and co.commentTime between #{entryTime} and #{entryTime1}
order by co.commentTime desc LIMIT #{page},#{limit}

select co.commentId,co.status,fo.name,co.commentInfo,co.comImg,co.commentTime from yh_health_lecture_comment co,yh_user_reginfo fo

co.usercode=fo.user_code 

	AND
	(
		tr.title like CONCAT('%',#{title},'%' )
	)


	and
	co.status = #{status,jdbcType=INTEGER}


and co.pid=#{pid,jdbcType=INTEGER}
order by co.commentTime desc LIMIT  #{page},#{limit}

select count(*) from yh_health_lecture_comment co,yh_user_reginfo fo

co.usercode=fo.user_code 

	AND
	(
		tr.title like CONCAT('%',#{title},'%' )
	)


	and
	co.status = #{status,jdbcType=INTEGER}


and co.pid=#{pid,jdbcType=INTEGER}
order by co.commentTime desc
